def flatten(items):
    out = []
    for x in items:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

if __name__ == "__main__":
    print(flatten([1, [2, 3, [4, [5]]], 6]))
